CREATE TABLE IF NOT EXISTS apps (
	id VARCHAR(255) NOT NULL, 
	title VARCHAR(500), 
	developer VARCHAR(500), 
	icon_url TEXT, 
	genre VARCHAR(255), 
	store_url TEXT NOT NULL, 
	store_rating FLOAT, 
	installs VARCHAR(100), 
	lang VARCHAR(10) NOT NULL, 
	country VARCHAR(10) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	last_synced_at TIMESTAMP WITHOUT TIME ZONE, 
	last_analyzed_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id)
);

ALTER TABLE "apps" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS llm_cache (
	key VARCHAR(64) NOT NULL, 
	provider VARCHAR(50) NOT NULL, 
	model VARCHAR(255) NOT NULL, 
	response JSONB NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (key)
);

ALTER TABLE "llm_cache" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS issues (
	id BIGSERIAL NOT NULL, 
	app_id VARCHAR(255) NOT NULL, 
	title VARCHAR(500) NOT NULL, 
	title_source VARCHAR(20) NOT NULL, 
	summary TEXT, 
	possible_impact TEXT, 
	suggested_investigation JSONB, 
	evidence_review_ids JSONB, 
	root_cause_confirmed BOOLEAN NOT NULL, 
	summary_model VARCHAR(255), 
	summary_warnings JSONB, 
	keywords JSONB, 
	category VARCHAR(50), 
	category_source VARCHAR(20) NOT NULL, 
	review_count INTEGER NOT NULL, 
	thumbs_up_total INTEGER NOT NULL, 
	priority_score FLOAT NOT NULL, 
	priority_label VARCHAR(20) NOT NULL, 
	priority_breakdown JSONB, 
	priority_override VARCHAR(20), 
	override_reason TEXT, 
	severity FLOAT NOT NULL, 
	confidence FLOAT NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	merged_into_id BIGINT, 
	is_active BOOLEAN NOT NULL, 
	centroid BYTEA, 
	last_run_id BIGINT, 
	first_seen_at TIMESTAMP WITHOUT TIME ZONE, 
	last_seen_at TIMESTAMP WITHOUT TIME ZONE, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(app_id) REFERENCES apps (id) ON DELETE CASCADE, 
	FOREIGN KEY(merged_into_id) REFERENCES issues (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_issues_app_active ON issues (app_id, is_active);

ALTER TABLE "issues" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS jobs (
	id BIGSERIAL NOT NULL, 
